import type { PlanRegistry } from "./model.ts";

/** Path of the generated offering module, from the package root. */
export const PLAN_OFFERING_MODULE = "src/plans/offering.generated.ts";

/**
 * The generated TypeScript module that carries the offering section of plans.yaml as data, so code that cannot
 * read a file (a browser bundle, an Edge Function, the marketing site) reads the same statuses as the loader.
 */
export function renderPlanOfferingModule(registry: PlanRegistry): string {
  return [
    "// Generated by `pnpm --filter @xos/schemas generate:plans` from packages/schemas/plans.yaml.",
    "// Never edit by hand; on a merge conflict, take either side and rerun the generator.",
    'import type { PlanOffering } from "./model.ts";',
    "",
    "/** What is offered and on sale today: the offering section of plans.yaml. */",
    `export const PLAN_OFFERING: PlanOffering = ${JSON.stringify(registry.offering, null, 2)};`,
    "",
  ].join("\n");
}
